      "element_id": "prisma_2020_1_e2",
      "status": "PRESENT",
      "chunk_id": "marginalia_0",
      "quote": "Prognostic value of procalcitonin in acute exacerbation of chronic obstructive pulmonary disease: A systematic review and metaanalysis.",
